mapper.select:
SELECT ml.id, ml.name, ml.level_value, ml.upgrade_condition, ml.benefits, ml.status, ml.effective_time, ml.remark, ml.creator, ml.create_time, ml.updater, ml.update_time, COUNT(mu.id) AS member_count FROM member_level ml LEFT JOIN member_user mu ON mu.level_id = ml.id
AND ml.name LIKE CONCAT('%', #{reqVO.name}, '%')
AND ml.level_value = #{reqVO.levelValue}
AND ml.upgrade_condition LIKE CONCAT('%', #{reqVO.upgradeCondition}, '%')
AND ml.benefits LIKE CONCAT('%', #{reqVO.benefits}, '%')
AND ml.status = #{reqVO.status}
AND ml.effective_time = #{reqVO.effectiveTime}
AND ml.remark LIKE CONCAT('%', #{reqVO.remark}, '%')
AND ml.creator = #{reqVO.creator}
AND ml.create_time BETWEEN #{reqVO.createTime[0]} AND #{reqVO.createTime[1]}
AND ml.updater = #{reqVO.updater}
AND ml.update_time BETWEEN #{reqVO.updateTime[0]} AND #{reqVO.updateTime[1]}
GROUP BY ml.id ORDER BY ml.id DESC
